SELECT sku, gtin, name, pack, case_units, flow, price_inr, cost_inr
FROM store.products
WHERE name ILIKE '%atta%' OR pack ILIKE '%5 kg%' OR name ILIKE '%flour%';

SELECT * FROM store.stock_counts WHERE sku='ATTA-WW-5KG' ORDER BY count_ts;
SELECT * FROM store.write_offs WHERE sku='ATTA-WW-5KG' ORDER BY date;
SELECT * FROM store.store_orders WHERE sku='ATTA-WW-5KG' ORDER BY created_ts;

SELECT min(date) AS min_d, max(date) AS max_d, count(*) AS rows FROM store.daily_sales;
SELECT min(audit_ts) AS min_a, max(audit_ts) AS max_a, count(*) AS rows FROM store.shelf_audits;
SELECT min(date) AS min_d, max(date) AS max_d FROM store.inventory_book;
SELECT min(bill_ts) AS min_b, max(bill_ts) AS max_b FROM store.pos_lines;

SELECT date, sku, units_sold FROM store.daily_sales
WHERE date IN ('2026-06-24','2026-06-25','2026-06-12','2026-06-26')
ORDER BY date, sku;

SELECT sum(units_sold) AS units_june, sum(revenue_inr) AS revenue_june, count(*) AS days_with_rows
FROM store.daily_sales
WHERE sku='ATTA-WW-5KG' AND date >= '2026-06-01' AND date < '2026-07-01';

SELECT count(DISTINCT bill_id) AS bills_pay FROM payments.pos_payments;
SELECT count(DISTINCT bill_id) AS bills_lines FROM store.pos_lines;
SELECT count(*) AS pay_bills_without_lines
FROM (SELECT DISTINCT bill_id FROM payments.pos_payments) p
WHERE NOT EXISTS (SELECT 1 FROM store.pos_lines l WHERE l.bill_id=p.bill_id);
SELECT min(qty) AS min_qty, max(qty) AS max_qty, count(*) FILTER (WHERE qty<=0) AS nonpos FROM store.pos_lines;
